	/** Collects variable declarations, explicit tuple reads and unknown operators in a single condition traversal. */
	@InternalUseOnly
	public static ConditionFacts conditionFacts(ValueExpr condition) {
		boolean[] complete = { true };
		boolean[] containsSubQuery = { false };
		boolean[] opaquePath = { false };
		Set<String> variableNames = new LinkedHashSet<>();
		Set<String> bindingNames = new LinkedHashSet<>();
		condition.visit(new AbstractQueryModelVisitor<RuntimeException>() {
			private List<QueryModelNode> functionChildren;

			@Override
			protected void meetNode(QueryModelNode node) {
				List<QueryModelNode> parentFunctionChildren = functionChildren;
				if (parentFunctionChildren != null) {
					parentFunctionChildren.add(node);
				}
				List<QueryModelNode> currentFunctionChildren = node instanceof FunctionCall ? new ArrayList<>() : null;
				functionChildren = currentFunctionChildren;
				boolean opaqueNode = false;
				if (node instanceof Var variable && !variable.hasValue()) {
					variableNames.add(variable.getName());
				}
				if (node instanceof SubQueryValueOperator) {
					containsSubQuery[0] = true;
				}
				// Function calls evaluate their declared arguments, including the pinned preparation subclass. Their
				// visitor must also expose those same arguments; check that after visiting the direct children.
				if (node instanceof ValueExpr expression && !scalarReadsAreExplicit(expression)) {
					// Unknown expressions own their input contract, including reads not represented by Var children.
					complete[0] = false;
					opaqueNode = true;
				}
				if (node instanceof TupleExpr tuple) {
					if (!tupleReadsAreExplicit(tuple)) {
						complete[0] = false;
						opaqueNode = true;
					} else if (!opaquePath[0]) {
						// Subqueries also correlate through declared VALUES columns without Var children.
						bindingNames.addAll(tuple.getBindingNames());
						if (tuple instanceof BindingSetAssignment values) {
							bindingNames.addAll(values.getPossibleBindingNames());
						}
					}
				}
				boolean previousOpaquePath = opaquePath[0];
				opaquePath[0] |= opaqueNode;
				try {
					super.meetNode(node);
				} finally {
					opaquePath[0] = previousOpaquePath;
					functionChildren = parentFunctionChildren;
				}
				if (node instanceof FunctionCall call
						&& !functionArgumentsMatchChildren(call, currentFunctionChildren)) {
					complete[0] = false;
				}
			}

			@Override
			public void meetOther(QueryModelNode node) {
				if (node instanceof ValueExpr) {
					complete[0] = false;
				}
				super.meetOther(node);
			}
		});
		bindingNames.addAll(variableNames);
		return new ConditionFacts(new ConditionBindingReads(bindingNames, complete[0]), variableNames,
				containsSubQuery[0]);
	}

