	private static ConditionBindingScope forGate(Filter filter, TupleExpr argument, boolean scopeChange,
			Function<TupleExpr, Set<String>> bindingNames, ConditionFacts facts) {
		ConditionBindingScope explicit = filter.getConditionBindingScope();
		if (!explicit.isAuto()) {
			return explicit;
		}
		Set<String> names = facts.variableNames();
		if (isPartOfSubQuery(argument)
				|| !facts.containsSubQuery() && bindingNames.apply(argument).containsAll(names)) {
			return ConditionBindingScope.ALL;
		}
		Set<String> retained = new LinkedHashSet<>(bindingNames.apply(argument));
		if (filter.getCondition() instanceof Exists exists) {
			retained.addAll(bindingNames.apply(exists.getSubQuery()));
		}
		QueryModelNode child = argument;
		QueryModelNode parent = child.getParentNode();
		boolean prospectiveGate = true;
		while (parent != null && !retained.containsAll(names)) {
			boolean changesScope = prospectiveGate ? scopeChange
					: child != filter && child instanceof TupleExpr tuple && TupleExprs.isVariableScopeChange(tuple);
			if (changesScope) {
				break;
			}
			if (parent instanceof Join join && join.getRightArg() == child) {
				retained.addAll(bindingNames.apply(join.getLeftArg()));
			} else if (parent instanceof LeftJoin join && join.getRightArg() == child) {
				retained.addAll(bindingNames.apply(join.getLeftArg()));
			} else if (parent instanceof Lateral lateral && lateral.getRightArg() == child) {
				retained.addAll(lateral.getRightInputBindingNames());
			}
			prospectiveGate = false;
			child = parent;
			parent = parent.getParentNode();
		}
		return ConditionBindingScope.retain(retained);
	}

	public static boolean isPartOfSubQuery(QueryModelNode node) {
		for (QueryModelNode current = node; current != null; current = current.getParentNode()) {
			if (current instanceof SubQueryValueOperator) {
				return true;
			}
		}
		return false;
	}
